import assert from 'node:assert/strict';
import { chromium } from '../frontend/node_modules/playwright/index.js';

const mode = process.argv[2] ?? 'signup-and-login';
const baseUrl = '<PRIVATE_URL_0251>';
const username = 'acceptance_20260928_0610';
const email = '<ACCOUNT_EMAIL_076>';
const password = '<CREDENTIAL_VALUE_REMOVED>';

const browser = await chromium.launch({
  executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  headless: true,
  args: ['--no-sandbox'],
});

const page = await browser.newPage();

async function logIn() {
  await page.getByRole('link', { name: 'Sign in' }).click();
  await page.getByPlaceholder('Email').fill(email);
  await page.getByPlaceholder('Password').fill(password);
  const [response] = await Promise.all([
    page.waitForResponse(response => response.url().endsWith('/api/users/login')),
    page.getByRole('button', { name: 'Sign in' }).click(),
  ]);
  assert.equal(response.status(), 200, `login returned ${response.status()}`);
  await page.getByRole('link', { name: username }).waitFor({ state: 'visible' });
}

try {
  const navigation = await page.goto(baseUrl, { waitUntil: 'networkidle' });
  assert.equal(navigation?.status(), 200, `home page returned ${navigation?.status()}`);
  assert.equal(await page.title(), 'Conduit');

  if (mode === 'signup-and-login') {
    await page.getByRole('link', { name: 'Sign up' }).click();
    await page.getByPlaceholder('Username').fill(username);
    await page.getByPlaceholder('Email').fill(email);
    await page.getByPlaceholder('Password').fill(password);
    const [response] = await Promise.all([
      page.waitForResponse(response => response.url().endsWith('/api/users')),
      page.getByRole('button', { name: 'Sign up' }).click(),
    ]);
    assert.equal(response.status(), 201, `signup returned ${response.status()}`);
    await page.getByRole('link', { name: username }).waitFor({ state: 'visible' });

    await page.getByRole('link', { name: 'Settings' }).click();
    await page.getByRole('button', { name: 'Or click here to logout.' }).click();
  }

  await logIn();
  console.log(JSON.stringify({ mode, homeStatus: 200, signup: mode === 'signup-and-login', login: true, username }));
} finally {
  await browser.close();
}

